import pandas as pd
import numpy as np


def _plan_equal(p1, p2):
    n1 = pd.isna(p1)
    n2 = pd.isna(p2)
    if n1 and n2:
        return True
    if n1 or n2:
        return False
    return p1 == p2


def run(inputs: dict) -> dict:
    dim = inputs["DIM_ACCOUNT"].copy()
    stg = inputs["STG_ACCOUNT"].copy()

    # normalize date columns to pandas Timestamp (NaT for null end dates)
    dim["eff_start_date"] = pd.to_datetime(dim["eff_start_date"])
    dim["eff_end_date"] = pd.to_datetime(dim["eff_end_date"])
    stg["update_date"] = pd.to_datetime(stg["update_date"])

    # Build in-memory structure: account_id -> list of version dicts
    account_versions = {}

    for _, row in dim.iterrows():
        aid = row["account_id"]
        ver = {
            "plan": row["plan"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"] if pd.notna(row["eff_end_date"]) else None,
            "is_current": int(row["is_current"]),
        }
        account_versions.setdefault(aid, []).append(ver)

    # Sort staging by account_id, update_date ascending
    stg_sorted = stg.sort_values(by=["account_id", "update_date"], kind="mergesort").reset_index(drop=True)

    for _, srow in stg_sorted.iterrows():
        aid = srow["account_id"]
        s_plan = srow["plan"]
        s_date = srow["update_date"]

        if aid not in account_versions:
            account_versions[aid] = []

        versions = account_versions[aid]

        if len(versions) == 0:
            versions.append({
                "plan": s_plan,
                "eff_start_date": s_date,
                "eff_end_date": None,
                "is_current": 1,
            })
            continue

        # find version covering s_date: start <= d < end (end None = open/infinite)
        covering = None
        for v in versions:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if start <= s_date and (end is None or s_date < end):
                covering = v
                break

        if covering is None:
            # earliest version by eff_start_date
            f = min(versions, key=lambda v: v["eff_start_date"])
            versions.append({
                "plan": s_plan,
                "eff_start_date": s_date,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            v = covering
            if _plan_equal(v["plan"], s_plan):
                # no-op
                pass
            elif s_date == v["eff_start_date"]:
                v["plan"] = s_plan
            else:
                # split
                versions.append({
                    "plan": s_plan,
                    "eff_start_date": s_date,
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                })
                v["eff_end_date"] = s_date
                v["is_current"] = 0

    # Build output
    out_rows = []
    for aid, versions in account_versions.items():
        for v in versions:
            out_rows.append({
                "account_id": aid,
                "plan": v["plan"],
                "eff_start_date": v["eff_start_date"],
                "eff_end_date": v["eff_end_date"],
                "is_current": v["is_current"],
            })

    out_df = pd.DataFrame(out_rows, columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"])

    if not out_df.empty:
        out_df = out_df.sort_values(
            by=["account_id", "eff_start_date"], kind="mergesort"
        ).reset_index(drop=True)
        out_df["is_current"] = out_df["is_current"].astype(int)

    return {"dim_account_out": out_df}
